source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Locate the 3x3 rings that mark the centers of the repeated 2-lines.
    rings = []
    for r in range(h - 2):
        for c in range(w - 2):
            patch = [grid[y][c:c + 3] for y in range(r, r + 3)]
            if patch[1][1] == 2 and all(
                patch[y][x] == (2 if (y, x) == (1, 1) else 3)
                for y in range(3) for x in range(3)
            ):
                rings.append((r + 1, c + 1, r, c))

    row_lines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w * 0.7]
    col_lines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h * 0.7]
    horizontal = len(row_lines) >= len(col_lines)

    for cr, cc, top, left in rings:
        if horizontal:
            # Continue perpendicular to the horizontal 2-lines through the ring center.
            for r in range(h):
                if r < top or r > top + 2:
                    if out[r][cc] == 0:
                        out[r][cc] = 1
            for line in row_lines:
                for c in (cc - 1, cc + 1):
                    if 0 <= c < w:
                        for r in (line - 1, line + 1):
                            if 0 <= r < h and out[r][c] == 0:
                                out[r][c] = 1
        else:
            # Continue perpendicular to the vertical 2-lines through the ring center.
            for c in range(w):
                if c < left or c > left + 2:
                    if out[cr][c] == 0:
                        out[cr][c] = 1
            for line in col_lines:
                for r in (cr - 1, cr + 1):
                    if 0 <= r < h:
                        for c in (line - 1, line + 1):
                            if 0 <= c < w and out[r][c] == 0:
                                out[r][c] = 1
    return out
'''
